from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in store:
            return True
        _, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # purge expired entries lazily is optional, but check this key
            if key in store:
                if is_expired(key, t):
                    del store[key]

            if key in store:
                # update existing, move to end (most recently used)
                store.move_to_end(key)
                store[key] = (value, t)
            else:
                if len(store) >= capacity:
                    # evict least recently used, but first check if evicting expired ones could help
                    # Standard LRU: evict the least recently used entry regardless of expiry
                    store.popitem(last=False)
                store[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)

    return results

